export type MsgKey = keyof typeof en;
type Table = Record<MsgKey, Msg>;

/** The engine's catalog: English complete, German, Spanish and Polish complete (checked by the type). */
export const ENGINE_MESSAGES = { en: en as Table, de: de as Table, es: es as Table, pl: pl as Table };

/** t(key, params, lang): one engine message in a language (default: the current one). */
export const msg = makeT<MsgKey>(ENGINE_MESSAGES);

/** For other modules that want an engine string (field labels, source tags…). */
export function engineMessage(key: MsgKey, params: Params = {}, lang: Lang = getLang()): string {
  return msg(key, params, lang);
}

/** The words for a source tag in a language: "Your number", "Ihre Zahl", "Tu número", "Twoja liczba". */
export function sourceLabel(s: Source, lang: Lang = getLang()): string {
  return msg(`source.${s}` as MsgKey, {}, lang);
}

export type { Table as MessageTable };
